export type UpdateArchiveAccountLimitsRequest = { expected_revision: Revision, quota_bytes: ByteCount, pin_quota_bytes: ByteCount, max_active: number, max_capture_records: ByteCount, pin_deadline_seconds: number, cache_ttl_seconds: number, };

export type UpdateArchiveCollectionRequest = { expected_revision: Revision, label: EntryName, media_capacity_bytes: ByteCount, };

export type UpdateArchiveCopyRequest = { expected_revision: Revision, location: string, reported_burned_at_ms: TimestampMs | null, label: EntryName, health: ArchiveCopyHealth | null, };

export type UpdateGrantRequest = { expected_revision: Revision, capabilities: Array<Capability>, };

export type UpdatePoolRequest = { expected_revision: Revision, capacity_bytes: ByteCount, };

export type UpdatePrincipalRequest = { expected_revision: Revision, disabled: boolean, administrator: boolean, };

export type UpdateQuotaCeilingRequest = { expected_revision: Revision, quota_ceiling_bytes: ByteCount, };

export type UpdateRootManagementRequest = { expected_revision: Revision, display_name: EntryName, quota_bytes: ByteCount, expected_upload_interval_seconds: ByteCount | null, };

export type UpdateRootRequest = { expected_revision: Revision, display_name: EntryName, state: RootState, placement: Placement, quota_bytes: ByteCount, };

export type UploadId = string & { readonly __brand: "UploadId" };

export type UploadInspection = { id: UploadId, root_id: RootId, operation_id: OperationId, state: SessionState, expires_at_ms: TimestampMs, copies: Array<CopyProgress>, result: CommitReceipt | null, };

export type VersionCount = number;

export type VersionId = string & { readonly __brand: "VersionId" };

export type VersionPage = { versions: Array<FileVersion>, next_cursor: CursorToken | null, };

export type VersioningMode = "independent_files" | "atomic_directory";
